"use client";
import { FormEvent, useCallback, useEffect, useState } from "react";
import Link from "next/link";
type Group = { id: string; name: string; status: string; _count: { students: number; courseAssignments: number; assignments: number } };
export default function TeacherGroupsPage() { const [groups, setGroups] = useState<Group[]>([]); const [name, setName] = useState(""); const [error, setError] = useState(""); const load = useCallback(async () => { const response = await fetch("/api/teacher/groups", { cache: "no-store" }); const payload = await response.json().catch(() => null); if (response.ok) setGroups(payload.data ?? []); else setError(payload?.error ?? "Unable to load groups."); }, []); useEffect(() => { void load(); }, [load]); const create = async (event: FormEvent) => { event.preventDefault(); const response = await fetch("/api/teacher/groups", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, activate: true }) }); const payload = await response.json().catch(() => null); if (!response.ok) { setError(payload?.error ?? "Unable to create group."); return; } setName(""); void load(); }; return <section className="space-y-6"><header><h2 className="text-3xl font-bold">Groups</h2><p className="mt-2 text-slate-600">Create groups and add registered learners.</p></header><form onSubmit={create} className="flex max-w-xl gap-3 rounded-xl border bg-white p-4"><input value={name} onChange={(event) => setName(event.target.value)} minLength={2} required placeholder="New group name" className="min-w-0 flex-1 rounded-lg border px-3 py-2"/><button className="rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white">Create</button></form>{error ? <p className="rounded-lg bg-red-50 p-3 text-red-800">{error}</p> : null}{groups.length === 0 ? <div className="rounded-2xl border border-dashed bg-white p-8 text-slate-600">No groups yet. Create one to start assigning courses and work.</div> : <div className="grid gap-4 md:grid-cols-2">{groups.map((group) => <Link key={group.id} href={`/teacher/groups/${group.id}`} className="rounded-2xl border bg-white p-5 hover:border-blue-300"><div className="flex justify-between gap-3"><h3 className="text-xl font-bold">{group.name}</h3><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-semibold">{group.status}</span></div><p className="mt-4 text-sm text-slate-600">{group._count.students} learners · {group._count.courseAssignments} courses · {group._count.assignments} assignments</p></Link>)}</div>}</section>; }
